17	// Outcomes that need to happen after the TUI exits.
18	// - `Quit` propagates a full-app exit (q pressed anywhere in this loop or a
19	//   nested viewer like show/search).
20	// - `Resume`/`LaunchNewSession` `exec` into another process.
21	// `Show` doesn't go here because it runs inline within the loop, so hitting
22	// back in the transcript viewer drops us back to this list.
23	enum Action {
24	    Quit,
25	    Resume(String, String), // (id, cwd)
26	    LaunchNewSession(NewSessionConfig),
27	}
28	
29	/// Returns `Ok(true)` if the user pressed `q` (full app quit) anywhere within
30	/// the sessions TUI or a nested viewer (show/search). `Ok(false)` for a
31	/// normal back-out, JSON mode, or empty list.
32	pub fn run(all: bool, json: bool) -> Result<bool> {
33	    let conn = db::connect()?;
34	
35	    let repos = fetch_repos(&conn)?;
36	    let cwd_env = env::current_dir().ok().map(|p| p.to_string_lossy().to_string());
37	    let current_repo_id: Option<i64> = cwd_env.as_deref()
38	        .and_then(|cwd| repos.iter().find(|r| cwd.starts_with(r.directory.as_str())))
39	        .map(|r| r.id as i64);
40	
41	    let mut sessions = session_list::fetch(Scope::All, all);
42	
43	    // Pin sessions belonging to the current repo to the top while preserving
44	    // recency-DESC within each group, and remember which sessions are local so
45	    // the renderer can flag them with a star. session_id → repo_id lookup
46	    // happens here (one query) so we don't run it per row.
47	    let mut local_sessions: HashSet<String> = HashSet::new();
48	    if let Some(current) = current_repo_id {
49	        let repo_id_for: std::collections::HashMap<String, i64> = {
50	            let mut map = std::collections::HashMap::new();
51	            if let Ok(mut stmt) = conn.prepare(
52	                "SELECT session_id, repo_id FROM sessions WHERE repo_id IS NOT NULL"
53	            ) {
54	                if let Ok(rows) = stmt.query_map([], |row| {
55	                    Ok::<(String, i64), rusqlite::Error>((row.get(0)?, row.get(1)?))
56	                }) {
57	                    for r in rows.flatten() { map.insert(r.0, r.1); }
58	                }
59	            }
60	            map
61	        };
62	        // Local set: sessions whose repo_id matches the current repo, plus any
63	        // session whose cwd is within the repo's directory (catches untracked
64	        // JSONL-only sessions augmented by session_list::fetch).
65	        let current_dir = repos.iter().find(|r| r.id as i64 == current)
66	            .map(|r| r.directory.clone()).unwrap_or_default();
67	        for s in &sessions {
68	            let by_id = repo_id_for.get(&s.session_id) == Some(&current);
69	            let by_cwd = !current_dir.is_empty() && s.cwd.starts_with(current_dir.as_str());
70	            if by_id || by_cwd { local_sessions.insert(s.session_id.clone()); }
71	        }
72	        sessions.sort_by(|a, b| {
73	            let a_local = local_sessions.contains(&a.session_id);
74	            let b_local = local_sessions.contains(&b.session_id);
75	            b_local.cmp(&a_local).then(b.updated_at.cmp(&a.updated_at))
76	        });
77	    }
78	
79	    if json {
80	        let arr: Vec<serde_json::Value> = sessions.iter().map(|s| serde_json::json!({
81	            "session_id": s.session_id,
82	            "session_name": s.session_name,
83	            "cwd": s.cwd,
84	            "branch": s.branch,
85	            "author": s.author,
86	            "agent": s.agent_name,
87	            "updated_at": s.updated_at.to_rfc3339(),
88	            "backed_up": s.backed_up,
89	        })).collect();
90	        println!("{}", serde_json::to_string_pretty(&serde_json::json!({ "sessions": arr }))?);
91	        return Ok(false);
92	    }
93	
94	    if sessions.is_empty() {
95	        println!("No sessions found.");
96	        return Ok(false);
97	    }
98	
99	    let orig_hook = std::panic::take_hook();
100	    std::panic::set_hook(Box::new(move |info| {
101	        let mut out = io::stdout();
102	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
103	        let _ = terminal::disable_raw_mode();
104	        orig_hook(info);
105	    }));
106	
107	    let mut stdout = io::stdout();
108	    terminal::enable_raw_mode()?;
109	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
110	
111	    let action = tui_loop(&mut stdout, &mut sessions, &local_sessions, &repos);
112	
113	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
114	    terminal::disable_raw_mode()?;
115	
116	    let quit_app = matches!(action, Some(Action::Quit));
117	    match action {
118	        Some(Action::Quit) => {}
119	        Some(Action::Resume(id, cwd)) => { super::show::resume_session(&id, &cwd); }
120	        Some(Action::LaunchNewSession(cfg)) => { status::launch_new_session(cfg); }
121	        None => {}
122	    }
123	
124	    Ok(quit_app)
125	}
