127	/// Find the tracked repo that contains a session's cwd, falling back to the
128	/// caller-supplied default (e.g. the current working dir's repo) when the
129	/// session is from outside any tracked repo. Returns `None` only if no repo
130	/// could be determined at all — callers should bail in that case.
131	fn repo_for_session<'a>(s: &DisplaySession, repos: &'a [Repository], fallback: Option<&'a Repository>) -> Option<&'a Repository> {
132	    repos.iter().find(|r| s.cwd.starts_with(r.directory.as_str())).or(fallback)
133	}
134	
135	// Screens on the navigation stack. Only one variant today, but the stack
136	// shape mirrors status.rs::Screen so future drill-down screens can slot in
137	// the same way (push to enter, pop to back out).
138	enum Screen {
139	    Sessions { sel: usize },
140	}
141	
142	// Commands produced inside the key-handling match arms and executed after the
143	// borrow on `stack` ends. Mirrors the Cmd enum in status.rs.
144	enum Cmd {
145	    None,
146	    Break,
147	    Back,
148	    Show(String),
149	    Resume(String, String),                  // (session_id, cwd)
150	    Delete(String),                          // session_id
151	    Search(String),
152	    NewWorktree(String, String),             // (repo_dir, branch)
153	    NewSession(NewSessionConfig),
154	    Tidy(String),                            // repo_dir
155	    Redraw,
156	}
157	
158	fn tui_loop(
159	    stdout: &mut impl Write,
160	    sessions: &mut Vec<DisplaySession>,
161	    local_sessions: &HashSet<String>,
162	    repos: &[Repository],
163	) -> Option<Action> {
164	    // Fallback for `n`/`s`/`t` when the selected session's cwd doesn't match
165	    // any tracked repo (e.g. JSONL-only sessions from before init): prefer the
166	    // repo for the current working directory.
167	    let cwd_now = env::current_dir().ok().map(|p| p.to_string_lossy().to_string());
168	    let cwd_repo: Option<&Repository> = cwd_now.as_deref()
169	        .and_then(|cwd| repos.iter().find(|r| cwd.starts_with(r.directory.as_str())));
170	
171	    let mut stack: Vec<Screen> = vec![Screen::Sessions { sel: 0 }];
172	    let mut awaiting_delete = false;
173	    let mut flash: Option<&'static str> = None;
174	
175	    loop {
176	        let (w, h) = terminal::size().unwrap_or((120, 40));
177	        let w = w as usize;
178	        let h = h as usize;
179	
180	        match stack.last().unwrap() {
181	            Screen::Sessions { sel } => { draw(stdout, sessions, local_sessions, *sel, w, h, flash).ok(); }
182	        }
183	
184	        let cmd = match event::read().ok()? {
185	            Event::Key(k) => match stack.last_mut().unwrap() {
186	                Screen::Sessions { sel } => match k.code {
187	                    KeyCode::Char('q') => Cmd::Break,
188	                    KeyCode::Esc => Cmd::Back,
189	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
190	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
191	                        terminal::disable_raw_mode().ok();
192	                        std::process::exit(0);
193	                    }
194	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
195	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < sessions.len() { *sel += 1; } Cmd::None }
196	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
197	                    KeyCode::Char('G') => { *sel = sessions.len().saturating_sub(1); Cmd::None }
198	                    KeyCode::Char(' ') | KeyCode::Right | KeyCode::Enter => {
199	                        if sessions.is_empty() { Cmd::None }
200	                        else { Cmd::Show(sessions[*sel].session_id.clone()) }
201	                    }
202	                    KeyCode::Char('r') => {
203	                        if sessions.is_empty() { Cmd::None }
204	                        else {
205	                            let s = &sessions[*sel];
206	                            Cmd::Resume(s.session_id.clone(), s.cwd.clone())
207	                        }
208	                    }
209	                    KeyCode::Char('d') if !sessions.is_empty() => {
210	                        awaiting_delete = true;
211	                        flash = Some("  Delete session? Press y to confirm, any other key to cancel  ");
212	                        Cmd::None
213	                    }
214	                    KeyCode::Char('y') if awaiting_delete => {
215	                        awaiting_delete = false;
216	                        flash = None;
217	                        Cmd::Delete(sessions[*sel].session_id.clone())
218	                    }
219	                    KeyCode::Char('/') => match super::collect_search_query(stdout, w, h) {
220	                        Some(q) if !q.trim().is_empty() => Cmd::Search(q),
221	                        _ => Cmd::Redraw,
222	                    },
223	                    KeyCode::Char('n') => {
224	                        let repo = sessions.get(*sel)
225	                            .and_then(|s| repo_for_session(s, repos, cwd_repo));
226	                        if let Some(repo) = repo {
227	                            match super::collect_text_input(stdout, "  new worktree branch: ", w, h) {
228	                                Some(b) if !b.trim().is_empty() => {
229	                                    Cmd::NewWorktree(repo.directory.clone(), b.trim().to_string())
230	                                }
231	                                _ => Cmd::Redraw,
232	                            }
233	                        } else { Cmd::Redraw }
234	                    }
235	                    KeyCode::Char('s') => {
236	                        let repo = sessions.get(*sel)
237	                            .and_then(|s| repo_for_session(s, repos, cwd_repo))
238	                            .or(cwd_repo);
239	                        if let Some(repo) = repo {
240	                            match status::new_session_wizard(stdout, &repo.directory, w, h) {
241	                                Some(cfg) => Cmd::NewSession(cfg),
242	                                None => Cmd::Redraw,
243	                            }
244	                        } else { Cmd::Redraw }
245	                    }
246	                    KeyCode::Char('t') => {
247	                        let repo = sessions.get(*sel)
248	                            .and_then(|s| repo_for_session(s, repos, cwd_repo))
249	                            .or(cwd_repo);
250	                        match repo {
251	                            Some(r) => Cmd::Tidy(r.directory.clone()),
252	                            None => Cmd::None,
253	                        }
254	                    }
255	                    _ => { awaiting_delete = false; flash = None; Cmd::None }
256	                }
257	            },
258	            Event::Resize(_, _) => Cmd::Redraw,
259	            _ => Cmd::None,
260	        };
261	
262	        match cmd {
263	            Cmd::None => {}
264	            Cmd::Break => return Some(Action::Quit),
265	            Cmd::Back => {
266	                stack.pop();
267	                if stack.is_empty() { break; }
268	            }
269	            Cmd::Show(id) => {
270	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
271	                terminal::disable_raw_mode().ok();
272	                let result = super::show::run(&id);
273	                terminal::enable_raw_mode().ok();
274	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
275	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
276	                match result {
277	                    Ok(true) => return Some(Action::Quit),
278	                    Err(_) => { flash = Some("  Transcript not found — run `gossamer index` to backfill  "); }
279	                    Ok(false) => {}
280	                }
281	            }
282	            Cmd::Resume(id, cwd) => return Some(Action::Resume(id, cwd)),
283	            Cmd::Delete(id) => {
284	                super::clean::remove_session(&id).ok();
285	                sessions.retain(|s| s.session_id != id);
286	                if let Some(Screen::Sessions { sel }) = stack.last_mut() {
287	                    if *sel >= sessions.len() && !sessions.is_empty() { *sel = sessions.len() - 1; }
288	                }
289	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
290	            }
291	            Cmd::Search(query) => {
292	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
293	                terminal::disable_raw_mode().ok();
294	                let quit_app = super::search::run(&query, 10, false).unwrap_or(false);
295	                terminal::enable_raw_mode().ok();
296	                if quit_app { return Some(Action::Quit); }
297	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
298	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
299	            }
300	            Cmd::NewWorktree(repo_dir, branch) => {
301	                let msg = status::create_worktree(&repo_dir, &branch);
302	                let display: String = msg.chars().take(w).collect();
303	                let padded = format!("{:<width$}", display, width = w);
304	                execute!(stdout, cursor::MoveTo(0, (h - 1) as u16)).ok();
305	                write!(stdout, "\x1b[7m{padded}\x1b[0m").ok();
306	                stdout.flush().ok();
307	            }
308	            Cmd::NewSession(cfg) => return Some(Action::LaunchNewSession(cfg)),
309	            Cmd::Tidy(repo_dir) => {
310	                if let Some(r) = repos.iter().find(|r| r.directory == repo_dir) {
311	                    super::tidy::tui_tidy(stdout, std::slice::from_ref(r), 7, false, w, h);
312	                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
313	                }
314	            }
315	            Cmd::Redraw => { execute!(stdout, terminal::Clear(ClearType::All)).ok(); }
316	        }
317	    }
318	
319	    None
320	}
