322	fn draw(
323	    stdout: &mut impl Write,
324	    sessions: &[DisplaySession],
325	    local_sessions: &HashSet<String>,
326	    sel: usize,
327	    w: usize,
328	    h: usize,
329	    flash: Option<&str>,
330	) -> io::Result<()> {
331	    let t = crate::theme::get();
332	    // Reserve the leading cell only if at least one row will use the star.
333	    // Otherwise we'd lose two columns of width for no visible benefit (e.g.
334	    // when not invoked from inside a tracked repo).
335	    let any_local = sessions.iter().any(|s| local_sessions.contains(&s.session_id));
336	
337	    let content_h = h.saturating_sub(2); // 1 header + 1 status bar
338	    let scroll = if sel >= content_h { sel + 1 - content_h } else { 0 };
339	
340	    // Pre-compute column widths
341	    let name_w = sessions.iter().map(|s| s.session_name.trim().chars().count()).max().unwrap_or(0).min(40);
342	    let cwd_w  = sessions.iter().map(|s| short_cwd(&s.cwd).chars().count()).max().unwrap_or(0);
343	    let branch_w = sessions.iter().map(|s| s.branch.chars().count()).max().unwrap_or(0);
344	    let author_w = sessions.iter().map(|s| s.author.chars().count()).max().unwrap_or(0);
345	    let tokens_w = {
346	        let w = sessions.iter().map(|s| session_list::fmt_tokens(s.tokens_used).chars().count()).max().unwrap_or(0);
347	        if w > 0 { w.max(6) } else { 0 }
348	    };
349	
350	    // ── Header row ────────────────────────────────────────────────────────────
351	    execute!(stdout, cursor::MoveTo(0, 0))?;
352	    {
353	        let dm = t.text_dim;
354	        let star_gap = if any_local { "  " } else { "" };
355	        let mut hdr = format!("{star_gap}  {:<name_w$}", "session");
356	        if cwd_w   > 0 { hdr.push_str(&format!("  {:<cwd_w$}",    "directory")); }
357	        if branch_w > 0 { hdr.push_str(&format!("  {:<branch_w$}", "branch")); }
358	        if author_w > 0 { hdr.push_str(&format!("  {:<author_w$}", "author")); }
359	        if tokens_w > 0 { hdr.push_str(&format!("  {:>tokens_w$}", "tokens")); }
360	        hdr.push_str("  id        updated");
361	        let display: String = hdr.chars().take(w).collect();
362	        write!(stdout, "\x1b[{dm}m{display}\x1b[0m")?;
363	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
364	    }
365	
366	    for row in 0..content_h {
367	        execute!(stdout, cursor::MoveTo(0, (row + 1) as u16))?;
368	        let idx = scroll + row;
369	        if idx >= sessions.len() {
370	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
371	            continue;
372	        }
373	
374	        let s = &sessions[idx];
375	        let is_sel = idx == sel;
376	
377	        let id_short: String = s.session_id.chars().take(8).collect();
378	        let ts = relative_time(s.updated_at);
379	        let age = (Utc::now() - s.updated_at).num_seconds().max(0);
380	        let dot_col = match age {
381	            a if a < 900   => t.fresh,
382	            a if a < 3_600 => t.moderate,
383	            _              => t.text_dim,
384	        };
385	        let (meta_col, dot_char) = if s.backed_up {
386	            (t.backed_meta, "★")
387	        } else {
388	            (t.unbacked_meta, "·")
389	        };
390	        // Name color is driven by whether the user explicitly named the
391	        // session (`/rename` or custom-title), not by whether it's been
392	        // checkpointed. Explicit names always pop; derived first-prompt
393	        // fallbacks render dim regardless of backed_up.
394	        let name_col = if s.name_is_explicit {
395	            t.backed_name
396	        } else if s.backed_up {
397	            t.text_secondary
398	        } else {
399	            t.unbacked_name
400	        };
401	        let branch_col = if s.backed_up { t.link } else { t.stale };
402	
403	        let clean = session_list::sanitize_one_line(&s.session_name);
404	        let name: String = clean.chars().take(name_w).collect();
405	        let name_padded = format!("{:<name_w$}", name);
406	
407	        let cwd_short = short_cwd(&s.cwd);
408	        let cwd_padded = format!("{:<cwd_w$}", cwd_short);
409	
410	        let star_prefix = if any_local {
411	            if local_sessions.contains(&s.session_id) {
412	                format!("\x1b[{fc}m★\x1b[0m ", fc = t.fresh)
413	            } else {
414	                "  ".to_string()
415	            }
416	        } else {
417	            String::new()
418	        };
419	
420	        let mut line = format!(
421	            "{star_prefix}\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m  \x1b[{dm}m{cwd_padded}\x1b[0m",
422	            dm = t.text_dim,
423	        );
424	
425	        if branch_w > 0 {
426	            let b: String = s.branch.chars().take(branch_w).collect();
427	            let pad = " ".repeat(branch_w - b.chars().count());
428	            line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
429	        }
430	
431	        if author_w > 0 {
432	            let a: String = s.author.chars().take(author_w).collect();
433	            let pad = " ".repeat(author_w - a.chars().count());
434	            line.push_str(&format!("  \x1b[{dm}m{a}{pad}\x1b[0m", dm = t.text_dim));
435	        }
436	
437	        if tokens_w > 0 {
438	            let tok = session_list::fmt_tokens(s.tokens_used);
439	            let pad = " ".repeat(tokens_w - tok.chars().count());
440	            let tk = session_list::token_color(s.tokens_used);
441	            line.push_str(&format!("  \x1b[{dm}m{pad}\x1b[{tk}m{tok}\x1b[0m", dm = t.text_dim));
442	        }
443	
444	        line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
445	
446	        if is_sel {
447	            let bg = crate::theme::get().sel_bg;
448	            let colored = super::with_bg(&line, bg);
449	            let vis = super::visible_width(&line);
450	            let pad = w.saturating_sub(vis);
451	            write!(stdout, "\x1b[{bg}m{colored}{}\x1b[0m", " ".repeat(pad))?;
452	        } else {
453	            write!(stdout, "{line}")?;
454	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
455	        }
456	    }
457	
458	    let base = format!(
459	        "  {} sessions   ↑↓/jk navigate   space: view   r: resume   d: delete   s: new session   n: new worktree   t: tidy   / search   q: quit  ",
460	        sessions.len()
461	    );
462	    let bar = if let Some(msg) = flash {
463	        let skip = msg.chars().count();
464	        let rest: String = base.chars().skip(skip).collect();
465	        format!("{msg}{rest}")
466	    } else { base };
467	    let display: String = bar.chars().take(w).collect();
468	    let padded = format!("{:<width$}", display, width = w);
469	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
470	    write!(stdout, "\x1b[7m{padded}\x1b[0m")?;
471	
472	    stdout.flush()
473	}
