476	fn relative_time(dt: DateTime<Utc>) -> String {
477	    let secs = (Utc::now() - dt).num_seconds().max(0);
478	    if secs < 604_800 {
479	        match secs {
480	            s if s < 60     => "just now".to_string(),
481	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
482	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
483	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
484	        }
485	    } else {
486	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
487	    }
488	}
