490	fn short_cwd(cwd: &str) -> String {
491	    let home = std::env::var("HOME").unwrap_or_default();
492	    let path = if !home.is_empty() && cwd.starts_with(&home) {
493	        format!("~{}", &cwd[home.len()..])
494	    } else {
495	        cwd.to_string()
496	    };
497	    let parts: Vec<&str> = path.trim_end_matches('/').split('/').filter(|s| !s.is_empty()).collect();
498	    match parts.len() {
499	        0 => "/".to_string(),
500	        1 => format!("/{}", parts[0]),
