13	pub struct DisplaySession {
14	    pub session_id: String,
15	    pub session_name: String,
16	    pub cwd: String,
17	    pub branch: String,
18	    pub updated_at: DateTime<Utc>,
19	    pub agent_name: String,
20	    pub backed_up: bool,
21	    /// Display name of whoever initiated the session — taken from the author
22	    /// of the first checkpoint (lowest checkpoint_number). Empty for sessions
23	    /// that have never been checkpointed (live JSONL only) or whose author
24	    /// couldn't be resolved.
25	    pub author: String,
26	    /// True when session_name came from an explicit `/rename` (custom-title
27	    /// entry in the JSONL); false when it's the derived first-prompt fallback.
28	    /// Drives the italic/plain distinction in the list renderers.
29	    pub name_is_explicit: bool,
30	    /// Sum of output tokens generated across all assistant turns. 0 when the
31	    /// session has never been indexed or has no local JSONL.
32	    pub tokens_used: i64,
33	}
34	
35	/// SGR color for a token count — a graduated sequence using standard 16-color
36	/// ANSI so the terminal's own palette controls the actual RGB values.
37	///
38	/// Dark theme: dim → progressively brighter (more tokens = more visible).
39	/// Light theme: muted → progressively darker/more saturated.
40	pub fn token_color(tokens: i64) -> &'static str {
41	    if crate::theme::get().is_dark {
42	        match tokens {
43	            t if t < 5_000   => "90",   // dim gray   — trace usage
44	            t if t < 20_000  => "37",   // white      — light
45	            t if t < 100_000 => "33",   // yellow     — moderate
46	            t if t < 500_000 => "93",   // bright yellow — heavy
47	            _                => "1;31", // bold red   — very heavy
48	        }
49	    } else {
50	        match tokens {
51	            t if t < 5_000   => "90",   // light gray — trace usage
52	            t if t < 20_000  => "36",   // cyan       — light
53	            t if t < 100_000 => "34",   // blue       — moderate
54	            t if t < 500_000 => "35",   // magenta    — heavy
55	            _                => "1;31", // bold red   — very heavy
56	        }
57	    }
58	}
59	
60	/// Format a token count compactly for display (empty string for zero).
61	pub fn fmt_tokens(n: i64) -> String {
62	    if n <= 0 { return String::new(); }
63	    if n < 1_000 { return format!("{n}"); }
64	    if n < 10_000 { return format!("{:.1}k", n as f64 / 1_000.0); }
65	    if n < 1_000_000 { return format!("{}k", n / 1_000); }
66	    format!("{:.1}M", n as f64 / 1_000_000.0)
67	}
68	
69	/// Collapse interior whitespace (newlines, tabs, runs of spaces) into a single
70	/// space. session_name flows into fixed-width raw-mode columns; an interior
71	/// '\n' jumps the cursor and clobbers the row layout — see git history for
72	/// the bee0c590 incident. Cheap to do everywhere session_name is produced.
73	pub fn sanitize_one_line(text: &str) -> String {
74	    let mut out = String::with_capacity(text.len());
75	    let mut prev_space = false;
76	    for c in text.chars() {
77	        if c.is_whitespace() {
78	            if !prev_space && !out.is_empty() {
79	                out.push(' ');
80	                prev_space = true;
81	            }
82	        } else {
83	            out.push(c);
84	            prev_space = false;
85	        }
86	    }
87	    while out.ends_with(' ') { out.pop(); }
88	    out
89	}
