91	pub enum Scope<'a> {
92	    /// All tracked sessions across every repo.
93	    All,
94	    /// Sessions belonging to a single repo. Matched primarily by `repo_id`;
95	    /// older rows without `repo_id` are caught by `cwd LIKE <directory>%`.
96	    Repo(&'a Repository),
97	}
98	
99	/// Load sessions, optionally scoped to one repo. With `include_old = false`,
100	/// only sessions updated within the last 3 days are returned. Result is sorted
101	/// most-recent-first; callers are free to re-sort.
102	pub fn fetch(scope: Scope, include_old: bool) -> Vec<DisplaySession> {
103	    let cutoff = Utc::now() - chrono::Duration::days(3);
104	    let mut sessions = query_db(&scope);
105	    // Augment first, then cutoff-filter on the final updated_at. Otherwise a
106	    // DB row with a stale updated_at but an actively-touched local JSONL gets
107	    // dropped here, then re-added as unbacked when augment can't find it —
108	    // diverging from the repo view where include_old=true skips this filter.
109	    augment_with_jsonls(&mut sessions, &scope, include_old, cutoff);
110	    if !include_old {
111	        sessions.retain(|s| s.updated_at >= cutoff);
112	    }
113	    sessions.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
114	    sessions
115	}
116	
117	fn query_db(scope: &Scope) -> Vec<DisplaySession> {
118	    let Ok(conn) = db::connect() else { return Vec::new(); };
119	    let mut out: Vec<DisplaySession> = Vec::new();
120	    let map = |row: &rusqlite::Row<'_>| -> rusqlite::Result<DisplaySession> {
121	        let ts: String = row.get(4)?;
122	        let author_name: String = row.get(6)?;
123	        let author_email: String = row.get(7)?;
124	        let os_user: String = row.get(8)?;
125	        let raw_name: String = row.get(1)?;
126	        let name_is_explicit: i64 = row.get(9)?;
127	        let tokens_used: i64 = row.get(10)?;
128	        Ok(DisplaySession {
129	            session_id: row.get(0)?,
130	            session_name: sanitize_one_line(&raw_name),
131	            cwd: row.get(2)?,
132	            branch: row.get(3)?,
133	            updated_at: DateTime::parse_from_rfc3339(&ts)
134	                .map(|dt| dt.with_timezone(&Utc))
135	                .unwrap_or_else(|_| Utc::now()),
136	            agent_name: row.get(5)?,
137	            backed_up: true,
138	            author: resolve_author_label(&author_name, &author_email, &os_user),
139	            name_is_explicit: name_is_explicit != 0,
140	            tokens_used,
141	        })
142	    };
143	    // Pull the author of the FIRST checkpoint (lowest checkpoint_number) for
144	    // each session — that's whoever initiated the first message. Sessions
145	    // without checkpoints (shadow-only) get NULLs which COALESCE turns into
146	    // empty strings, leaving `author` blank.
147	    let cols = "
148	        s.session_id, s.session_name, s.cwd, COALESCE(s.branch,''),
149	        s.updated_at, s.agent_name,
150	        COALESCE(c.author_name, ''), COALESCE(c.author_email, ''), COALESCE(c.os_user, ''),
151	        s.name_is_explicit, COALESCE(s.tokens_used, 0)
152	    ";
153	    let join = "
154	        LEFT JOIN checkpoints c
155	          ON c.session_id = s.session_id
156	         AND c.checkpoint_id = (
157	               SELECT checkpoint_id FROM checkpoints
158	               WHERE session_id = s.session_id
159	               ORDER BY last_turn_ts ASC
160	               LIMIT 1
161	             )
162	    ";
163	    match scope {
164	        Scope::All => {
165	            let Ok(mut stmt) = conn.prepare(
166	                &format!("SELECT {cols} FROM sessions s {join} ORDER BY s.updated_at DESC")
167	            ) else { return out; };
168	            if let Ok(rows) = stmt.query_map([], map) {
169	                for r in rows.flatten() { out.push(r); }
170	            }
171	        }
172	        Scope::Repo(r) => {
173	            let Ok(mut stmt) = conn.prepare(&format!(
174	                "SELECT {cols} FROM sessions s {join}
175	                 WHERE s.repo_id = ?1 OR (s.repo_id IS NULL AND s.cwd LIKE ?2)
176	                 ORDER BY s.updated_at DESC"
177	            )) else { return out; };
178	            let pattern = format!("{}%", r.directory);
179	            if let Ok(rows) = stmt.query_map(rusqlite::params![r.id as i64, pattern], map) {
180	                for row in rows.flatten() { out.push(row); }
181	            }
182	        }
183	    }
184	    out
185	}
186	
187	fn cwd_os_user(cwd: &str) -> Option<String> {
188	    let rest = cwd.strip_prefix("/Users/").or_else(|| cwd.strip_prefix("/home/"))?;
189	    let user = rest.split('/').next()?;
190	    if user.is_empty() { None } else { Some(user.to_string()) }
191	}
192	
193	fn resolve_author_label(name: &str, email: &str, os_user: &str) -> String {
194	    if !name.trim().is_empty() { return name.to_string(); }
195	    if !email.trim().is_empty() { return email.to_string(); }
196	    if !os_user.trim().is_empty() { return os_user.to_string(); }
197	    String::new()
198	}
199	
200	fn augment_with_jsonls(
201	    sessions: &mut Vec<DisplaySession>,
202	    scope: &Scope,
203	    include_old: bool,
204	    cutoff: DateTime<Utc>,
205	) {
206	    let Ok(home) = std::env::var("HOME") else { return; };
207	    let projects = PathBuf::from(&home).join(".claude/projects");
208	    let Ok(dirs) = std::fs::read_dir(&projects) else { return; };
209	
210	    for dir_entry in dirs.flatten() {
211	        let dir = dir_entry.path();
212	        if !dir.is_dir() { continue }
213	        let Ok(files) = std::fs::read_dir(&dir) else { continue };
214	        for f in files.flatten() {
215	            let path = f.path();
216	            if path.extension().and_then(|e| e.to_str()) != Some("jsonl") { continue }
217	            let Some(session_id) = path.file_stem().and_then(|s| s.to_str()).map(str::to_string)
218	                else { continue };
219	
220	            let file_mtime = f.metadata().ok()
221	                .and_then(|m| m.modified().ok())
222	                .map(DateTime::<Utc>::from)
223	                .unwrap_or_else(Utc::now);
224	            if !include_old && file_mtime < cutoff { continue }
225	
226	            let parsed = parse_jsonl(&path);
227	
228	            if let Some(existing) = sessions.iter_mut().find(|s| s.session_id == session_id) {
229	                if !parsed.session_name.is_empty() { existing.session_name = parsed.session_name; }
230	                if file_mtime > existing.updated_at { existing.updated_at = file_mtime; }
231	                if !parsed.branch.is_empty() { existing.branch = parsed.branch; }
232	                // A custom-title in the JSONL outranks the DB flag. Without
233	                // this, /rename'd sessions stay tagged as "derived" until the
234	                // next index run, so they render gray in the lists.
235	                if parsed.name_is_explicit { existing.name_is_explicit = true; }
236	                // JSONL token count is authoritative when present (live data).
237	                if parsed.tokens_used > 0 { existing.tokens_used = parsed.tokens_used; }
238	                // Sessions inserted by the SessionStart hook but never indexed
239	                // from a checkpoint branch have no `checkpoints` row, so the
240	                // author column came back empty. Fall back to the cwd's
241	                // os-user — same fallback used for brand-new untracked rows.
242	                if existing.author.is_empty() {
243	                    let cwd = if !existing.cwd.is_empty() { existing.cwd.as_str() } else { parsed.cwd.as_str() };
244	                    existing.author = cwd_os_user(cwd).unwrap_or_default();
245	                }
246	                continue;
247	            }
248	
249	            // Untracked session (only in local JSONL). When scoped to one
250	            // repo, only include if its cwd actually belongs to that repo.
251	            if let Scope::Repo(r) = scope {
252	                if !parsed.cwd.starts_with(r.directory.as_str()) { continue }
253	            }
254	
255	            let author = cwd_os_user(&parsed.cwd).unwrap_or_default();
256	            sessions.push(DisplaySession {
257	                session_id,
258	                session_name: parsed.session_name,
259	                cwd: parsed.cwd,
260	                branch: parsed.branch,
261	                updated_at: file_mtime,
262	                agent_name: "Claude Code".to_string(),
263	                backed_up: false,
264	                author,
265	                name_is_explicit: parsed.name_is_explicit,
266	                tokens_used: parsed.tokens_used,
267	            });
268	        }
269	    }
270	}
271	
272	struct ParsedJsonl {
273	    session_name: String,
274	    cwd: String,
275	    branch: String,
276	    name_is_explicit: bool,
277	    tokens_used: i64,
278	}
279	
280	fn parse_jsonl(path: &Path) -> ParsedJsonl {
281	    let mut out = ParsedJsonl {
282	        session_name: String::new(),
283	        cwd: String::new(),
284	        branch: String::new(),
285	        name_is_explicit: false,
286	        tokens_used: 0,
287	    };
288	    let Ok(file) = std::fs::File::open(path) else { return out; };
289	    let reader = std::io::BufReader::new(file);
290	    let mut last_prompt = String::new();
291	    let mut custom_title = String::new();
292	
293	    for line in reader.lines().flatten() {
294	        let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
295	        match v["type"].as_str() {
296	            Some("custom-title") => {
297	                if let Some(t) = v["customTitle"].as_str() {
298	                    if !t.trim().is_empty() { custom_title = t.to_string(); }
299	                }
300	            }
301	            Some("user") | Some("system") => {
302	                if out.cwd.is_empty() {
303	                    if let Some(c) = v["cwd"].as_str() { out.cwd = c.to_string(); }
304	                }
305	            }
306	            Some("assistant") => {
307	                if let Some(n) = v["message"]["usage"]["output_tokens"].as_i64() {
308	                    out.tokens_used += n;
309	                }
310	            }
311	            _ => {}
312	        }
313	        if v["type"].as_str() == Some("user") {
314	            if let Some(t) = user_text(&v["message"]["content"]) {
315	                last_prompt = t;
316	            }
317	        }
318	        if let Some(b) = v["gitBranch"].as_str() {
319	            if !b.is_empty() { out.branch = b.to_string(); }
320	        }
321	    }
322	    if !custom_title.is_empty() {
323	        out.session_name = custom_title;
324	        out.name_is_explicit = true;
325	    } else {
326	        out.session_name = last_prompt;
327	    }
328	    out.session_name = sanitize_one_line(&out.session_name);
329	    out
330	}
331	
332	fn user_text(content: &serde_json::Value) -> Option<String> {
333	    match content {
334	        serde_json::Value::String(s) if !s.trim().is_empty() => Some(s.trim().to_string()),
335	        serde_json::Value::Array(blocks) => {
336	            blocks.iter().find_map(|b| {
337	                if b["type"].as_str() == Some("text") {
338	                    b["text"].as_str().filter(|t| !t.trim().is_empty()).map(|t| t.trim().to_string())
339	                } else { None }
340	            })
341	        }
342	        _ => None,
343	    }
344	}
